pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    if fitting_bins_count == 1 && post_residual < next_item_size {
        // Penalize placing an item that won't fit even if it's the last chance
        score += 50.0;
    }

    if post_residual > mean_residual {
        // Reward placements where residual is closer to the mean
        score -= (post_residual - mean_residual) * 2.0;
    }

    if next_item_size != 0 && post_residual < next_item_size / 4 {
        // Penalize placements that leave very little room for future items
        score += 30.0;
    }

    // New mutation: Reward larger bin capacities
    if bin_capacity > 1024 {
        score -= (bin_capacity - 1024) as f64 * 0.5;
    }

    // New mutation: Penalize high open bins count
    if open_bins_count > 5 {
        score += (open_bins_count - 5) as f64 * 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Non-linear conditionals for better compaction
    if fitting_bins_count == 1 && post_residual < next_item_size {
        score += (next_item_size - post_residual) * 20.0;
    }

    if post_residual > mean_residual {
        score -= (post_residual - mean_residual) * 3.0;
    }

    // Fine-tuned thresholds for better bin utilization
    if next_item_size != 0 && post_residual < next_item_size / 4 {
        score += 25.0;
    }

    // Lookahead trade-offs to reduce total bins used
    if step_index > total_items / 2 {
        let lookahead_bins = (total_items - step_index) as f64 / mean_residual;
        score -= lookahead_bins * 10.0;
    }

    // Combine with bin capacity for better bin utilization
    score *= ((bin_capacity - bin_residual) as f64 / bin_capacity) + 0.5;

    // Apply weight adjustments
    let score = score * 0.75 + ((post_residual as f64) as f64) * 0.25;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // If the current bin can fit exactly one more item and the post-residual is smaller than the next item size
    if fitting_bins_count == 1 && post_residual < next_item_size {
        score += 50.0;
    }

    // Penalize if the post-residual is significantly larger than the mean residual
    if post_residual > mean_residual {
        score -= (post_residual - mean_residual) * 2.0;
    }

    // Reward if the next item size is not zero and the post-residual is smaller than half of the next item size
    if next_item_size != 0 && post_residual < next_item_size / 2 {
        score += 30.0;
    }

    // Introduce lookahead by considering the number of fitting bins
    if fitting_bins_count > 1 && post_residual < (bin_capacity - bin_residual) / fitting_bins_count {
        score += 20.0 * (fitting_bins_count as f64);
    }

    // Adjust the overall score by combining linear and non-linear components
    let score = score * 0.70 + ((post_residual as f64) as f64) * 0.30;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small gaps that cannot fit the next item
    if post_residual < next_item_size * 1.5 {
        score += (next_item_size - post_residual) as f64;
    }

    // Penalize open bins count to encourage filling existing bins
    score += (open_bins_count * 3.0) as f64;

    // Reward larger bin capacities more aggressively
    if bin_capacity > 150 {
        score -= ((bin_capacity - 120) * 0.8) as f64;
    }

    // Penalize low mean residual to avoid creating too many small bins
    if mean_residual < 30.0 {
        score += (30.0 - mean_residual) as f64;
    }

    // Reward fitting multiple items in a bin
    if fitting_bins_count > 1 {
        score -= (fitting_bins_count * 2.0) as f64;
    }

    score
}

